ART = 'артбук The Art of Silver Pines'

N = []  # nodes
E = []  # edges
def node(id, type, label, text='', src=None, **kw):
    d = dict(id=id, type=type, label=label, text=text, src=src or [])
    d.update(kw); N.append(d); return id
def edge(a, b, kind, note=''):
    E.append(dict(source=a, target=b, kind=kind, note=note))

# ---------------- центр
node('Q', 'q', 'Что случилось в Silver Pines?', 'Детектива Рэда Уокера наняли найти пропавшего музыканта Эдди Вельвета. Чем глубже он копает, тем больше дело похоже на его собственное. Доска собирает факты из игры и её артбука, внешние источники, гипотезы и доводы за и против.')

# ---------------- персонажи
C = {}
def char(id, label, text, src=None, **kw):
    C[id] = node(id, 'char', label, text, src, **kw)
char('red', 'Рэд Уокер', 'Частный детектив, протагонист. Просыпается в пустой закусочной «Шахтёр», не помнит дороги. Нанят по телефону искать Эдди. В диалогах — портрет в очках, в игре — тёмное пальто. В баре просит «просто воды».', [])
char('eddie', 'Эдди Вельвет', 'Пропавший музыкант из Орегона. Жил в люксе «Гризли» мотеля «Багровый медведь», 17 сентября объявлен его последний концерт в баре Rabbit Hole. Главный подозреваемый в исчезновении Элис. Носит красную куртку: портрет в диалогах, полароид с Элис. В финале: «Дело было не в городе... дело было во мне».', [])
char('alice', 'Элис Бейкер', 'Пропавшая местная девушка, квартира 4B в «Юнионе». Её дневник обращён к Эдди. «Любимица города, настоящий ангел… у неё была другая сторона». В финальной зоне её тело лежит на мелководье под скалами.', [])
char('jackman', 'Мистер Джекман', 'Клиент. Только голос в трубке таксофона, каждое сохранение — звонок ему. Сначала «найди Эдди», потом «покончи с ним». Обещает пляж, пальмы и бесконечный синий океан.', [], aka='Hank Jackman (по фанатским источникам)')
char('little', 'Маленький человек', 'Безымянный «коротышка» из дневника Элис и чужих рассказов. По домофону её квартиры отвечает: «Друг, детектив». Голос из интеркома (по внешним источникам — он): «Элис была для меня целым миром», «для Эдди ты — ангел милосердия». В «Покое» — Сервер в бабочке, он же Бледный Гарсон, и секретный босс: «Посмотри, что он сделал с моей девочкой… Это должен быть ты!» В артбуке у него своя страница — The Little Man.', [ext(ART + ', с. 42–43', '')])
char('foster', 'Отец Джейкоб Фостер', 'Священник Чёрч-Хилла, к началу игры мёртв: рак, но жил «благодаря несгибаемой воле». В дневнике пишет, как водил Элис к морю и как после встречи с музыкантом её раны открылись снова. Его тело кремируют по ходу головоломки.', [])
char('room3', 'Женщина из номера 3', 'Плачет за дверью мотеля, а по телефону спокойно даёт код 6671 и просит выпить с ней. В концовке «Покой» сидит в баре и рассказывает Рэду прошлое Эдди как его собственное.', [])
char('cowboy', 'Ковбой', 'Бармен Rabbit Hole, «напарник». Помогает Рэду, дарит талисман и патроны, потом погибает, обороняя кафе. В «Покое» жив: «Готов к последнему родео?»', [ext(ART + ', с. 18–19', '')], aka='в артбуке Bartender · внешность Tom Fothergill (Team17)')
char('roberts', 'Помощник шерифа Робертс', 'Встречает у парома и советует уехать. Заперт в собственной допросной, отдаёт плёнку с допросом Эдди. Превращается в босса: «Эдди… такой же, как я, такой же, как и вы».', [])
char('oldcop', 'Старик в плаще с магнумом', 'Враждебный крупный мужчина, по гайдам — шериф или «старый коп». В артбуке его зовут Бутс, и разработчики называют его тёмным отражением Уокера. Валит Рэда на землю, «буду за тобой следить», требует уехать. В канализации душит Рэда, тот стреляет. «Увидимся... В аду» — «Хотя я уже в аду».', [ext(ART + ', с. 22–23', '')], aka='Бутс (Boots) в артбуке · голос Glenn Wrage')
char('wulfe', 'Шериф Вульф', 'Шериф — женщина, есть только в документах: записка «брать Вельвета, пусть понервничает», жалоба на пропажи из хранилища улик.', [])
char('oldman', 'Добрый старик с зонтом', 'Встречается на мосту и в автобусе. Жил с женой в «Юнионе». Уговаривает не губить себя: «Никто никому ничего не должен, кроме как умереть». На прощание: «Похоже, выбор у тебя был с самого начала».', [])
char('sadgirl', 'Девушка из ветклиники', 'Сидела в клетке, её укусил «жуткий карлик», который «пришёл за девушкой в воде». У телецентра говорит Рэду, что он похож на Эдди, и умирает.', [ext('пересказ сцены у телецентра, NPC Tips', U['npc'])])
char('digger', 'Копатель', 'Роет яму за станцией канатки и не собирается вылезать: «Здесь внизу лучше. Сейчас я счастливее, чем когда-либо».', [])
char('burnt', 'Обожжённый', 'Моет обожжённые руки у воды: «Я всё сжёг… Только так он оставил меня в покое. Коротышка доберётся и до тебя». Ключ к концовке «Жизнь»: велит сжечь мементо в печи. В фанатских источниках — Дрю.', [])
char('driver', 'Водитель', 'Злодей местного сериала «Terminal Drive». Записки «Водитель знает, что вы сделали… I see you». Нападает в мэрии и на съёмочной площадке.', [])
char('laker', 'Художник Дрю Лейкер', 'Жил в квартире 1C «Юниона», погиб, упав с балкона. Отменённая выставка «Скорбь», недописанный женский портрет, надпись под слоями краски.', [])

