ev('b_1944', 'before', 1, 'Наводнение 1944 года', 'Шторм смыл старое здание, на его месте построили «кошмарный» «Юнион». Перед нынешней бурей по радио пугают: «если дамбы прорвёт, будет хуже, чем в сорок четвёртом».', [])
ev('b_mount', 'before', 2, 'С Элис что-то случилось на горе', 'Дневник Элис: с диаконом на Черч-Хилл она говорит «о том, что случилось в горах», и делает вид, что это помогает. Было это до Эдди: по дневнику Фостера, знакомство с музыкантом снова открыло её раны.', [ext('пересказ журнала, NPC Tips', U['npc'])])
ev('b_foster', 'before', 3, 'Отец Фостер водит Элис к морю', '«Несмотря ни на что, вода её успокаивает… Она падает куда-то, куда я не могу дотянуться». Позже он умирает от рака, который держал в секрете.', [])
ev('b_meet', 'before', 4, 'Эдди и Элис', 'Эдди играет в Rabbit Hole, Элис влюбляется («Эдди, Эдди, Эдди… мотель»), а потом пишет, что ненавидит его запах спиртного и сигарет. Маленький человек «не даёт ей уйти».', [])
ev('b_gig', 'before', 5, 'Последний концерт, 17 сентября', 'Афиша: Эдди Вельвет, 17 сентября, Rabbit Hole. В видении Сервер в бабочке говорит: «Эдди Вельвет. Его последний концерт».', [])
ev('b_car', 'before', 6, '17 сентября: ссора на горе', 'После концерта, на горном серпантине, Эдди и Элис ссорятся в машине. Плёнка кинопроектора в Красном мире: «He will kill us both… It was a mistake to say anything… Stop the car». Пьяный Эдди бьёт по тормозам, выгоняет Элис из машины и уезжает.', [])
ev('b_cliff', 'before', 7, 'Элис шагает с обрыва', 'Одна, ночью, в бурю на горе. На кассете LOVE женщина приставляет к виску пистолет, который ей дал Эдди: тот же код самоубийства. В финальной зоне её тело лежит на мелководье под скалами, с обручальным кольцом на руке.', [])
ev('b_crash', 'before', 11, 'Месяц спустя: октябрь 1993', 'В конце октября Эдди садится за руль. Шёпот из студии: «Красный свет... Без тормозов... Последний съезд». На той же горной дороге машина на полной скорости пробивает сетку-рабицу над обрывом и уходит под воду. Silver Pines — то, что видит тонущий Эдди.', [])
ev('b_missing', 'before', 8, 'Элис пропала, Эдди допрошен', 'Газеты: пропала мисс Бейкер, задержан «музыкант из другого города». На допросе: Элис видели с ним на канатке, а поездку на машине он «выдумал». — «Я её не убивал». Город кричит ему «Убийца!». Улик нет, и Эдди отпускают.', [])
ev('b_month', 'before', 9, 'Месяц трезвости', '26 сентября Эдди всё ещё живёт в люксе «Гризли» и две недели не платит за номер. Он не пьёт: надпись на жетоне «30 дней трезвости» почти стёрта от прикосновений. Месяц его гложет вина.', [])
ev('b_storm', 'before', 10, 'Буря века и эвакуация', 'Октябрь 1993. Мэр уверял, что эвакуация не нужна, потом город всё же опустел. Поиски Элис свернули из-за ветра.', [])
ev('g_wake', 'game', 1, 'Пробуждение в закусочной', 'Звёзды, голос, «путешествие к звёздам». Рэд у машины перед пустой закусочной. Звонит Джекман: «Нашёл Эдди Вельвета?»', [])
ev('g_bar', 'game', 2, 'Видение в Rabbit Hole', 'Бармен (Ковбой): «А кто сказал, что ты не спишь прямо сейчас?» Сервер в бабочке: «Эдди Вельвет. Его последний концерт»… «Я знаю его лучше, чем он сам себя». Эдди поёт на сцене.', [])
ev('g_bells', 'game', 3, 'Семь колоколов для канатки', 'Смотритель: канатка без колоколов не поедет, «может, кто-то не хочет, чтобы ты увидел, что там наверху». Пять колоколов из семи разбросаны по городу, их охраняют боссы. Мелодию задаёт табличка: E G D C F A B.', [])
ev('g_sheriff', 'game', 4, 'Участок: плёнка и отчёт', 'Робертс отдаёт плёнку с допросом Эдди, в архиве отчёт об утопленнике. Потом босс-Робертс.', [])
ev('g_union', 'game', 5, 'Квартира 4B и красная комната', 'Фото Эдди с Элис, дневник про дьякона и маленького человека. В красной комнате голос: «Маленький человек не отпускает меня». Голодную дыру надо накормить птицей.', [])
ev('g_church', 'game', 6, 'Чёрч-Хилл: голос за спиной', 'Голос маленького человека: «Её зовут Элис… любимица города, ангел… Эдди убил её. Спроси, кто дал ему право забрать её у нас».', [])
ev('g_sewer', 'game', 7, 'Канализация: выстрел в старика', 'Старик душит Рэда, Рэд стреляет. Джекман: «Ты действовал в целях самообороны. Человек мёртв. Дело закрыто».', [])
ev('g_order', 'game', 8, 'Новый заказ: убить Эдди', 'Джекман: «Эдди не покинет Silver Pines… Мне нужно, чтобы ты с ним покончил». — «Я частный детектив, мистер Джекман, а не наёмный убийца».', [])
ev('g_thelend', 'game', 9, 'Телецентр: кассеты Terminal Drive', 'Кассеты: «Ложь в зеркале заднего вида», «Красный свет», «Без тормозов», «Последний съезд». На экране: «Улыбнись, Элис, ты в телевизоре».', [])
ev('g_mercy', 'game', 10, '«Для Эдди ты ангел милосердия»', 'Голос по интеркому: «Элис была для меня целым миром… смерть Эдди — лучшее, что можно сделать… Убей Эдди, Уокер».', [])
ev('g_tree', 'game', 11, 'Эдди у мёртвого дерева', '«Дело было не в городе, дело было во мне. Я и есть кошмар… Если бы ты не встретил меня, ты был бы жив». Выбор: убить или уйти.', [])

# ---------------- концовки
END = {}
def endn(id, label, text, src):
    END[id] = node(id, 'ending', label, text, src)
endn('leave', 'Бегство (Leave)', 'Убить Эдди. Джекман по телефону: «Ты прикончил плохого парня… садись в машину… солнце, пальмы, бескрайний синий океан». Закадр Рэда: «Я сделал то, за чем приехал сюда. Не по своей воле. Не по здравому смыслу. Просто потому, что иначе было нельзя… Этих денег мне хватит, чтобы забыть Сильвер-Пайнс». Последняя фраза: «Вокруг тянется бесконечный лес, а дорога будто и не думает заканчиваться».', [ext('достижения Steam', U['ach'])])
