def sup(c, h, note=''): edge(c, h, 'supports', note)
def con(c, h, note=''): edge(c, h, 'contradicts', note)
def about(a, b, note=''): edge(a, b, 'about', note)
def echo(r, x, note=''): edge(r, x, 'echoes', note)
def leads(a, b): edge(a, b, 'leads')

