# ---------------- девушка в чёрном, кот, колокола
char('wib', 'Девушка в чёрном', 'Черноволосая девушка в чёрном. Ночью в даунтауне: «Не привыкла я прятаться. Люблю острые ощущения»; про Эдди — «Он опасен разве что для самого себя»; шутит, что «прямо сейчас выцарапает тебе глаза», и предупреждает о «таком же парне, как ты, в длинном плаще». У цветочного магазина: «Твой драгоценный Эдди», «Если бы мог, он бы посадил меня в клетку и выбросил ключ».', [ext(ART + ', с. 24–25', '')], aka='Джейд (Jade) в артбуке · голос и внешность Suzi Hunter')
char('cat', 'Чёрный кот', 'Попадается Рэду по всему городу. В квартире кошатницы Рэд здоровается с ним как со старым знакомым: «Привет. Это снова ты… На пароме я тебя не видел». В подвале ветклиники кот сидит в клетке, Рэд выпускает его: «По крайней мере, теперь ты свободен». За это — памятная вещь, кошачий ошейник.', [])

evd('c_bells', 'Мелодия для канатки', 'Семь колоколов подписаны по нотам: C D E F G A B. Табличка над ними, треснувшая на «EGD» и «CFAB», задаёт порядок: E G D C F A B. Когда мелодия сыграна, вспыхивает красное видение — Эдди обнимает Элис.', [])
evd('c_ring', 'Обручальное кольцо Элис', 'На руке мёртвой Элис в воде: «Потускневшее обручальное кольцо с простым дизайном». Второе кольцо лежит в шкатулке со звёздами в закусочной, которую хозяева купили в день свадьбы. Для «Покоя» нужны оба.', [])
evd('c_insult', '«Бесполезная куча дерьма»', 'Дневник Элис об Эдди кончается чужим голосом, капслоком: «Трогаешь то, что принадлежит другому. ПРИКОСНОВЕНИЯ БЕСПОЛЕЗНОЙ КУЧИ ДЕРЬМА!» Теми же словами Сервер в «Покое» кроет Рэда: «Бесполезный! Жалкий кусок дерьма…», «Бесполезный кусок дерьма... Ненавижу тебя».', [])
evd('c_month', '30 дней трезвости и 17 сентября', 'Последний концерт Эдди в Rabbit Hole — 17 сентября. На календаре в магазине октябрь 1993-го, газета пишет о женщине, пропавшей «на прошлой неделе». Жетон «30 дней трезвости» сходится по сроку: если Эдди бросил пить после той ночи, жетон отсчитывает как раз этот месяц.', [])
evd('c_redlabel', 'Имя «Red Walker»', 'Red Label — самый ходовой виски Johnnie Walker. Детектив носит имя бутылки и при этом не пьёт: просит «просто воды», а в памятных вещах лежит жетон «30 дней трезвости». Бармен в первом видении: «I don\'t drink» — «You\'re going to».', [ext('Johnnie Walker — Wikipedia', 'https://en.wikipedia.org/wiki/Johnnie_Walker')])
evd('c_bus', 'Попутчик в автобусе', 'Пожилой человек в шляпе, не Эдди: «Ты гоняешься за этим так, будто от этого зависит твоя жизнь... и даже не понимаешь почему?», «У тебя навязчивая идея. И однажды она тебя убьет». Рэд: «У меня нет выбора! Другого выхода нет. Я в ловушке». В ответ: «Это твоя жизнь, и только тебе решать».', [])
evd('c_cowboydead', '«Я думал, ты погиб»', 'В баре «Покоя» Рэд встречает Ковбоя, который погиб у него на глазах: «Я думал, ты погиб. Я видел…» — «Это место не всегда такое, каким кажется».', [])
evd('c_dawn', 'Элис на рассвете', '«Тебе нужно отпустить все это. Назад пути уже нет… Так уж все сложилось. И каждый из нас сыграл в этом свою роль. Пора перестать бороться... и просто отдохнуть». Рэд: «Тогда почему мне так паршиво?» — «Ты так долго боролся».', [])
evd('c_eyes', '«Выцарапаю тебе глаза»', 'Девушка в чёрном: «Кто знает, может, я прямо сейчас выцарапаю тебе глаза». У цветочного: «Я, возможно, даже сохраню твои красивые глаза в неприкосновенности...» Так грозит кошка.', [])
evd('c_cage', '«Посадил бы меня в клетку»', 'Девушка в чёрном про своего «друга»: «Если бы мог, он бы посадил меня в клетку и выбросил ключ… Ты бы мне помог? Если бы понадобилось». Друг этот — «настоящий чудак. Одержимый такой. Но не такой простой». Позже Рэд выпускает из клетки чёрного кота.', [])
evd('c_collar', 'Кошачий ошейник', 'Памятная вещь от кота из клетки: «Узорчатый колокольчик без язычка хранит молчание… слегка раскачивается». Немой колокольчик в игре, где канатку зовут колоколами.', [])

hyp('h_voice', 'Маленький человек — голос внутри Элис', 'Он «стучит внутри стены», на лестнице его «не было», а в дневнике Элис посреди её слов вдруг прорывается капслоком его ругань — та же, что у Сервера в «Покое». Пистолет Эдди против него бесполезен: «Он никогда не поймет. Пистолет так приятно держать в руках...»', 2, ['SuHo'])
hyp('h_month', 'Через месяц Эдди сам направил машину с обрыва', 'Концерт 17 сентября, на календаре октябрь 1993-го, журнал мотеля от 26 сентября, жетон «30 дней трезвости». Месяц Эдди не пьёт и сходит с ума от вины. В конце октября он разгоняет машину на той же горной дороге и пробивает сетку-рабицу над обрывом — там, где лежит третий кол. Машина уходит под воду, и тонущий Эдди придумывает детектива Рэда Уокера.', 3, ['SuHo'], status='verdict')
hyp('h_ghost', 'Рэд уже мёртв', 'В русских субтитрах Эдди говорит Рэду: «Если бы ты не встретил меня, ты был бы жив». 911 Рэда не слышит, дороги в город он не помнит, мёртвый Ковбой стоит за стойкой, а в «Жизни» Рэд «исчезает», пока из воды достают Эдди.', 1, ['SuHo'])
hyp('h_wibcat', 'Девушка в чёрном — это чёрный кот', 'Грозит выцарапать глаза, жалуется, что «друг» посадил бы её в клетку, и просит помочь, «если понадобится». В ветклинике Рэд выпускает из клетки чёрного кота, и тот дарит ошейник. Оба появляются там, где Рэду нужен намёк.', 2, ['SuHo'])
hyp('h_wibdark', 'Девушка в чёрном — тёмная сторона Элис', 'Элис — светлая «любимица города», у которой, по словам голоса в церкви, «была другая сторона». Черноволосая девушка любит музыку Эдди, ревниво зовёт его «твой драгоценный Эдди» и боится «друга», который запер бы её в клетке, как маленький человек не отпускает Элис.', 1, ['SuHo'])

ref('r_jwred', 'Johnnie Walker Red Label', 'Имя героя совпадает с маркой виски. Героя, который «больше не пьёт».', 'ГИПОТЕЗА', [ext('Johnnie Walker — Wikipedia', 'https://en.wikipedia.org/wiki/Johnnie_Walker')])
ref('r_poecat', '«Чёрный кот» Эдгара По', 'Рассказчик-пьяница в ярости выкалывает коту глаз, потом убивает жену и замуровывает тело в стене. Полицию к телу приводит кошачий вой из стены. В игре: пьющий Эдди, «выцарапаю тебе глаза», «стучит внутри стены» в дневнике Элис, чёрный кот в клетке.', 'ГИПОТЕЗА', [ext('The Black Cat — Wikipedia', 'https://en.wikipedia.org/wiki/The_Black_Cat_(short_story)')])
ref('r_blonde', 'Блондинка и брюнетка у Линча', '«Шоссе в никуда»: брюнетка Рене и блондинка Элис, обеих играет одна актриса. «Малхолланд Драйв»: Бетти и Рита. «Твин Пикс»: Лора и её черноволосая кузина Мэдди — снова одна актриса. В игре: светлая Элис и девушка в чёрном.', 'ГИПОТЕЗА', [ext('Lost Highway — Wikipedia', U['w_lost']), ext('Mulholland Drive — Wikipedia', U['w_mull'])])

