# ---------------- финальная версия, ложный след, 55-FAITH, артбук
evd('c_missing', 'Ориентировки: пропала Элис', 'В газетах и на ориентировках Элис Бейкер — пропавшая без вести, задержан «музыкант из другого города». Поиски сворачивают из-за ветра.', [])
evd('c_fence', 'Пробитая сетка над обрывом', 'На краю обрыва высокий забор из сетки-рабицы вырван, смят и выгнут к пропасти, будто сквозь него на полной скорости пролетела машина. Здесь из Красного мира вытаскивают третий кол, а под сеткой лежит страница дневника.', [])
evd('c_noreflect', 'Рэда нет на снимках', 'В фотогалерее мэрии среди чиновников и горожан лица Рэда нет: в стекле он не отражается.', [])
evd('c_faith', 'Звонок на 55-FAITH', 'Номер с полуразрушенного билборда — 55-FAITH, на кнопках 553-24-84. В будке отвечают: «Спасибо, что позвонил. Я ждал тебя». — «Простите? Я звоню сюда впервые». — «Твой звонок начался не тогда, когда ты набрал номер. А тогда, когда ты понял, что идти тебе больше некуда». — «Кто это?» — «Пока ты задаешься этим вопросом, происходит что-то еще. Но не спеши. Это ведь „тот самый момент, который длится вечно“, да?» — «Где вы это услышали?» В ответ молчание. «The Kind of Moment That Lasts Forever» — так называется платиновый трофей.', [ext('платиновый трофей, games.gg', U['ggach'])])
evd('c_artlittle', 'Артбук: The Little Man', 'В разделе «Боссы» у маленького человека своя страница — The Little Man. На портретах бледный мужчина в жилетке и красной бабочке: официант из Rabbit Hole и «Покоя». Подпись — про логику сна: персонажи рассказывают Уокеру противоречащие друг другу версии, и игрок сам решает, кому верить.', [ext(ART + ', с. 42–43', '')])
evd('c_artkey', 'Артбук: Эдди в лице Уокера', 'На ключ-арте красная фигура Эдди с буквой V на куртке вписана прямо в лицо Уокера. Разработчики пишут, что лицо Эдди в игре прятали специально: кто он такой — один из главных сюжетных узлов.', [ext(ART + ', с. 94–95, 86–87', '')])
evd('c_artredlight', 'Артбук: босс «Красный свет»', 'Босса, который вылезает из чрева Странного дерева, в артбуке зовут Red light — «Красный свет», как в шёпоте из телецентра. Подпись: вода, красный свет и гримасы боли повторяются по всей игре, пока Уокер спускается глубже в кошмар.', [ext(ART + ', с. 44–45', '')])
evd('c_artboots', 'Артбук: Бутс', 'Старика в плаще с магнумом зовут Boots, голос — Glenn Wrage. Разработчики называют его тёмным отражением Уокера: давит, угрожает и, похоже, знает о нём больше, чем говорит.', [ext(ART + ', с. 22–23', '')])
evd('c_artjade', 'Артбук: Джейд и кошка', 'Девушку в чёрном зовут Jade, голос и внешность — Suzi Hunter. В углу её разворота — силуэт чёрной кошки.', [ext(ART + ', с. 24–25, 30–31', '')])
evd('c_artholloway', 'Артбук: Холлоуэй', 'Первого босса, из туннеля, в артбуке зовут Holloway — как хозяина мотеля «Багровый медведь», который клялся в записке: «МЫ БУДЕМ ОТКРЫТЫ». В раннем плане мотеля этот босс нарисован черепом в подвале у котельной.', [ext(ART + ', с. 40–41, 80–81', '')])

hyp('h_stalker', 'Рэд — ревнивый сталкер', 'Версия, в которую игра заставляет поверить перед финалом. Рэд — одержимый сталкер: годами следил за Элис, приготовил ей кольцо, а когда столичный музыкант её увёз, полез на гору мстить. За: голос в исповедальне говорит об Элис как о собственности, маленький человек «стучит внутри стены», старик в канализации тяжелее Рэда на сорок пять кило, шкатулка для кольца, девушка у телецентра говорит Рэду: «Вы так похожи на него». Против: реальный мир Рэда не замечает. Его нет на снимках в мэрии, 911 его не слышит, лицензия просрочена, а в «Жизни» из воды достают Эдди.', 1, ['SuHo'], status='false')
